fn variance(data: &[f64; 256], len: i64) -> f64 with Mut, Panic, Div {
    // First pass: mean
    var sum = 0.0
    var i: i64 = 0
    while i < len {
        sum = sum + data[i]
        i = i + 1
    }
    let mean = sum / (len as f64)

    // Second pass: sum of squared deviations
    var ss = 0.0
    i = 0
    while i < len {
        let d = data[i] - mean
        ss = ss + d * d
        i = i + 1
    }
    ss / (len as f64)
}

