struct IntStack {
    data: [i64; 1024],
    len: i64
}

impl IntStack {
    fn new() -> IntStack {
        IntStack { data: [0; 1024], len: 0 }
    }

    fn push(self: &! IntStack, val: i64) with Mut, Panic {
        if self.len < 1024 {
            self.data[self.len] = val
            self.len = self.len + 1
        }
    }

    fn pop(self: &! IntStack) -> i64 with Mut, Panic {
        if self.len == 0 { return 0 }
        self.len = self.len - 1
        self.data[self.len]
    }

    fn peek(self: &IntStack) -> i64 with Panic {
        if self.len == 0 { return 0 }
        self.data[self.len - 1]
    }

    fn is_empty(self: &IntStack) -> bool {
        self.len == 0
    }
}

In Sounio, effects propagate upward through the call chain. If function `foo` calls function `bar`, and `bar` has effects `with Div, Panic`, then `foo` must also declare at least `Div, Panic` in its own `with` clause.

Example:
```sio
fn divide(a: f64, b: f64) -> f64 with Div, Panic {
    a / b
}

// This function calls divide, so it must declare Div and Panic too
fn average(x: f64, y: f64) -> f64 with Div, Panic {
    divide(x + y, 2.0)
}

// main() needs IO for println, plus Div and Panic from average
fn main() with IO, Div, Panic {
    let avg = average(10.0, 20.0)
    println("done")
}
```

A function with no `with` clause is pure — it cannot call any effectful functions. This is enforced at compile time.

