fn bubble_sort(buf: &! SortBuf) with Mut, Panic {
    var n = buf.len
    var swapped = true
    while swapped {
        swapped = false
        var i: i64 = 1
        while i < n {
            if buf.data[i - 1] > buf.data[i] {
                let temp = buf.data[i - 1]
                buf.data[i - 1] = buf.data[i]
                buf.data[i] = temp
                swapped = true
            }
            i = i + 1
        }
        n = n - 1
    }
}

